import scala.util.Using

// several resources, released in reverse order even if construction fails:
Using.Manager { use =>
  val in  = use(new FileInputStream("a"))
  val out = use(new FileOutputStream("b"))
  out.write(in.readAllBytes())          // owned resources only
}
// single resource, exceptions merged by severity:
Using.resource(new BufferedReader(new FileReader("f.txt")))(_.readLine())
